  for (const g of nuevos) L.push(`${EMOJI[g.categoria] || '📦'} <b>${S(g.monto)}</b>${g.descripcion ? ' — ' + esc(g.descripcion) : ''}`);
  L.push('', `Hoy llevas: <b>${S(r.total_hoy)}</b>`, `Este mes: <b>${S(r.total_mes)}</b>`);
